/**
 * Type definitions and configuration for Notes2Quiz Study Packs.
 * Study pack materials are dynamically generated by the AI backend.
 */

export interface MCQItem {
  id: string;
  question: string;
  options: string[];
  correctIndex: number;
  correctAnswer?: string;
  explanation: string;
  theme?: string;
  difficulty?: 'Low' | 'Medium' | 'High';
  mnemonic?: string;
  notes?: string;
}

export interface FlashcardItem {
  id: string;
  front: string;
  back: string;
  keyTerm?: string;
}

export interface ExamNotesSection {
  shortQuestions: { question: string; marks: number; answer: string }[];
  longQuestions: { question: string; marks: number; outline: string[] }[];
  mcqs: MCQItem[];
}

export interface RevisionDay {
  dayNumber: number;
  dateStr: string;
  topic: string;
  badge: string;
  duration: string;
  tasks: string[];
}

export interface ActiveRecallItem {
  id: string;
  question: string;
  hint: string;
  answer: string;
  concept: string;
}

export interface StudyPackData {
  simplifiedNotes: {
    title: string;
    sections: { heading: string; content: string }[];
  };
  keyPoints: {
    summary: string;
    points: string[];
  };
  mcqs: MCQItem[];
  flashcards: FlashcardItem[];
  examNotes: ExamNotesSection;
  revisionPlan: {
    examDate: string;
    totalDays: number;
    days: RevisionDay[];
  };
  activeRecall: ActiveRecallItem[];
  _fallbackShifted?: boolean;
  sessionTitle?: string;
  extractedThemes?: string[];
  pageCount?: number;
}

export interface StudySession {
  id: string;
  title: string;
  category: 'today' | 'previous' | 'courses';
  course?: string;
  timestamp: string;
  questionCount?: number;
  active?: boolean;
}

